function findPermutation(s) {
  const n = s.length + 1;
  const perm = Array.from({ length: n }, (_, k) => k + 1);
  let i = 0;

  while (i < s.length) {
    if (s[i] === 'I') {
      i++;
      continue;
    }
    let j = i;
    while (j < s.length && s[j] === 'D') {
      j++;
    }
    let left = i;
    let right = j;
    while (left < right) {
      [perm[left], perm[right]] = [perm[right], perm[left]];
      left++;
      right--;
    }
    i = j;
  }
  return perm;
}

