function findPermutation(s) {
  // Depth-first search that tries values in increasing order, so the first full match is the smallest.
  const n = s.length + 1;
  const used = new Array(n + 1).fill(false);
  const perm = [];
  // fall[p]: how many 'D' steps follow position p; that many smaller values must still be free.
  const fall = new Array(n).fill(0);
  for (let p = s.length - 1; p >= 0; p--) fall[p] = s[p] === 'D' ? fall[p + 1] + 1 : 0;
  const place = p => {
    if (p === n) return true;
    let freeBelow = 0;
    for (let v = 1; v <= n; v++) {
      if (used[v]) continue;
      const fits = p === 0 || (s[p - 1] === 'I' ? v > perm[p - 1] : v < perm[p - 1]);
      if (fits && freeBelow >= fall[p]) {
        used[v] = true;
        perm.push(v);
        if (place(p + 1)) return true;
        used[v] = false;
        perm.pop();
      }
      freeBelow++;
    }
    return false;
  };
  place(0);
  return perm;
}

