function generate(rand, size) {
  const length = size === 'large' ? 9999 : 1 + Math.floor(rand() * 9);
  const style = rand();
  let s = '';
  if (style < 0.15) {
    s = (rand() < 0.5 ? 'D' : 'I').repeat(length);
  } else if (style < 0.5) {
    // Runs of one letter, to exercise long decreasing stretches.
    while (s.length < length) s += (rand() < 0.5 ? 'D' : 'I').repeat(1 + Math.floor(rand() * (size === 'large' ? 60 : 4)));
    s = s.slice(0, length);
  } else {
    const chanceD = rand();
    for (let k = 0; k < length; k++) s += rand() < chanceD ? 'D' : 'I';
  }
  return [s];
}
